export const BODY: string = "\n<p>SVG وPNG هما الصيغتان الأهم للشعارات والرسوم، وتعملان بطريقتين مختلفتين تمامًا. واحدة تصف الأشكال بالمعادلات، والأخرى تحفظ البكسلات.</p>\n<p>هذا الفرق يقرر كل شيء: كيف تتكبّر الصورة، وكم يزن الملف، وأين يعمل، وكيف يُحرَّر.</p>\n<p>يشرح هذا المقال المتجه مقابل النقطي بلغة بسيطة، لتختار الصيغة الصحيحة في كل مرة.</p>\n<h2 id=\"what-is-vector\">ماذا يعني متجه؟</h2>\n<p>ماذا يعني متجه؟ صورة تصف الأشكال بالمعادلات الرياضية: خطوط ومنحنيات وألوان. يمكن تكبيرها إلى أي حجم دون فقدان الحدة.</p>\n<p>SVG هو أشهر صيغة متجهة على الويب. الشعارات والأيقونات والرسوم كلها تعمل بشكل ممتاز كمتجهات.</p>\n<h2 id=\"what-is-raster\">ماذا يعني نقطي؟</h2>\n<p>ماذا يعني نقطي؟ صورة تحفظ شبكة بكسلات ثابتة: كل بكسل له لون محدد. التكبير يكشف البكسلات ويجعل الصورة ضبابية.</p>\n<p>PNG وJPG صيغ نقطية. الصور الفوتوغرافية واللقطات كلها نقطية لأنها تحفظ تفاصيل معقدة لا يمكن وصفها بالمعادلات.</p>\n<h2 id=\"scaling-compared\">التكبير: SVG يفوز بالكامل</h2>\n<p>التكبير: SVG يفوز بالكامل. يمكن تكبير SVG إلى أي حجم دون فقدان الحدة، بينما PNG يضبب عند التكبير.</p>\n<p>للشعارات التي تظهر بأحجام مختلفة، SVG هو الخيار الصحيح دائمًا. لا يوجد منافس في التكبير.</p>\n<h2 id=\"file-size-compared\">حجم الملف: يعتمد على الصورة</h2>\n<p>حجم الملف: يعتمد على الصورة. للرسوم البسيطة، SVG أصغر بكثير. للصور المعقدة، PNG قد يكون أصغر.</p>\n<p>شعار بسيط كـSVG قد يزن كيلوبايتات قليلة، بينما PNG نفسه قد يزن مئات الكيلوبايتات. لكن صورة معقدة كـSVG قد تكون ضخمة.</p>\n<h2 id=\"transparency-compared\">الشفافية: تعادل</h2>\n<p>الشفافية: تعادل. كلتا الصيغتين تدعمان قناة ألفا الكاملة، والشفافية سليمة في كلتيهما.</p>\n<p>لا يوجد فائز واضح هنا. إذا كانت الشفافية هي كل ما يهمك، فكلتا الصيغتين تعملان بشكل ممتاز.</p>\n<h2 id=\"editing-compared\">التحرير: SVG يفوز للرسوم</h2>\n<p>التحرير: SVG يفوز للرسوم. يمكنك تعديل الأشكال والألوان والنص في SVG بسهولة، بينما PNG يحتاج إلى تحرير البكسلات.</p>\n<p>للرسوم، SVG أسهل في التحرير بكثير. غيّر لونًا أو شكلًا في ثوانٍ دون لمس بقية الصورة.</p>\n<h2 id=\"browser-support\">الدعم في المتصفحات والتطبيقات</h2>\n<p>الدعم في المتصفحات والتطبيقات: PNG يعمل في كل مكان دون استثناء، بينما SVG يعمل في المتصفحات الحديثة وبعض التطبيقات.</p>\n<p>للتوافق الكامل، PNG هو الخيار الآمن. SVG ينمو لكنه لم يصل إلى كل مكان بعد.</p>\n<h2 id=\"when-to-use-svg\">متى تستخدم SVG؟</h2>\n<p>متى تستخدم SVG؟ للشعارات والأيقونات والرسوم التي تحتاج إلى تكبير دون فقدان الحدة. SVG هو الخيار الصحيح للرسوم على الويب.</p>\n<p>استخدم SVG أيضًا عندما تحتاج إلى تحرير سهل أو حجم ملف صغير للرسوم البسيطة.</p>\n<h2 id=\"when-to-use-png\">متى تستخدم PNG؟</h2>\n<p>متى تستخدم PNG؟ للصور الفوتوغرافية واللقطات، وعندما تحتاج إلى توافق كامل مع كل الأنظمة والتطبيقات.</p>\n<p>استخدم PNG أيضًا عندما ترسل الصورة إلى نظام لا تعرف ما إذا كان يدعم SVG. PNG هو الخيار الآمن دائمًا.</p>\n<h2 id=\"converting-between-them\">التحويل بين SVG وPNG</h2>\n<p>للتحويل بين SVG وPNG، افتح الأداة في متصفحك وارفع الملفات وحوّلها. التحويل من SVG إلى PNG سهل، والعكس يحتاج إلى تتبع تقريبي.</p>\n<p>تذكر أن التحويل إلى PNG يفقد مرونة المتجه. احتفظ بـSVG الأصلي دائمًا لإعادة التحويل بأي مقياس.</p>\n<h2 id=\"practical-workflow\">سير عمل عملي للشعارات</h2>\n<p>سير عمل عملي للشعارات: صمّم الشعار كـSVG، واحتفظ به كأصل، وحوّل نسخًا إلى PNG لكل استخدام: موقع ووسائل تواصل وطباعة.</p>\n<p>بهذا تحصل على الأفضل من الصيغتين: مرونة SVG وتوافق PNG. الأصل المتجه هو مصدر كل نسخة.</p>\n<h2 id=\"verdict\">الحكم: أي صيغة تفوز؟</h2>\n<p>الحكم: أي صيغة تفوز؟ لا يوجد فائز مطلق. SVG يفوز للرسوم والشعارات، وPNG يفوز للصور الفوتوغرافية والتوافق.</p>\n<p>استخدم كل صيغة حيث تتفوق. الشعار كـSVG واللقطة كـPNG: هذا هو التقسيم الصحيح.</p>\n<h2 id=\"vector-in-animation\">الرسوم المتجهة في الرسوم المتحركة</h2>\n<p>الرسوم المتجهة في الرسوم المتحركة: SVG يدعم الرسوم المتحركة عبر CSS وJavaScript. PNG لا يدعم الحركة أبدًا.</p>\n<p>للرسوم المتحركة على الويب، SVG هو الخيار الصحيح. الحركة تجعل الرسوم حية وتفاعلية.</p>\n<h2 id=\"raster-in-photography\">الرسوم النقطية في التصوير الفوتوغرافي</h2>\n<p>الرسوم النقطية في التصوير الفوتوغرافي: الصور الفوتوغرافية نقطية بطبيعتها. لا يمكن وصف صورة فوتوغرافية بالمعادلات.</p>\n<p>للتصوير الفوتوغرافي، PNG أو JPG هما الخياران الصحيحان. SVG لا يناسب الصور الفوتوغرافية أبدًا.</p>\n<h2 id=\"raster-in-games\">الرسوم النقطية في الألعاب</h2>\n<p>الرسوم النقطية في الألعاب: الألعاب تستخدم الرسوم النقطية للنسيج والخلفيات، والمتجهات للواجهات والأيقونات. كل نوع له مكانه.</p>\n<p>محركات الألعاب تدعم كلا النوعين. استخدم المتجه للواجهات والنقطي للعوالم المعقدة.</p>\n<h2 id=\"hybrid-workflows\">سير عمل هجين بالصيغتين</h2>\n<p>سير عمل هجين بالصيغتين: صمّم كـSVG، وحوّل إلى PNG للنشر، واحتفظ بالأصل المتجه. النهج الهجين يعطيك الأفضل من الصيغتين.</p>\n<p>لا تلتزم بصيغة واحدة. استخدم كل صيغة حيث تتفوق، وسيكون عملك أفضل.</p>\n<h2 id=\"teaching-vector-raster\">تعليم المتجه مقابل النقطي</h2>\n<p>تعليم المتجه مقابل النقطي: اشرح الفرق بمثال بسيط: المتجه مثل وصفة يمكن تكبيرها، والنقطي مثل صورة فوتوغرافية ثابتة.</p>\n<p>وللخطوات العملية، استخدم <a href=\"/ar/tahwil-svg-ila-png/\">محول SVG إلى PNG</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-svg-ila-png/\">كيفية تحويل SVG إلى PNG</a> و<a href=\"/ar/blog/dalil-tahwil-svg-ila-png/\">الدليل الكامل لتحويل SVG إلى PNG</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكن تحويل PNG إلى SVG حقيقي؟","answer":"لا، لا يمكن تحويل PNG إلى SVG حقيقي. يمكن تتبع الصورة لإنشاء متجه تقريبي، لكن النتيجة ليست SVG أصليًا."},{"question":"لماذا يبدو SVG مختلفًا في متصفحات مختلفة؟","answer":"لأن المتصفحات تعرض SVG بشكل مختلف قليلًا: الخطوط والتأثيرات قد تختلف. اختبر SVG في عدة متصفحات قبل النشر."},{"question":"هل SVG أفضل من PNG لشعارات المواقع؟","answer":"نعم، SVG أفضل لشعارات المواقع: يتكبّر دون فقدان الحدة، وحجمه صغير، ويبدو حادًا على كل الشاشات."},{"question":"هل يمكنني استخدام ملفات SVG في وورد وباوربوينت؟","answer":"وورد وباوربوينت الحديثان يدعمان SVG، لكن الإصدارات القديمة لا تدعمه. إذا لم تكن متأكدًا، فاستخدم PNG."},{"question":"ماذا يحدث للرسوم المتحركة SVG عند التحويل إلى PNG؟","answer":"التحويل إلى PNG يحفظ الإطار الأول فقط ويفقد الحركة. الرسوم المتحركة SVG لا تنتقل إلى PNG."},{"question":"هل أحفظ SVG بعد التحويل إلى PNG؟","answer":"نعم، احتفظ بـSVG بعد التحويل. SVG هو الأصل الذي يمكنك إعادة التحويل منه بأي مقياس مستقبلًا."}];
